package net.officefloor.hq.app.grade;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/grades")
@Validated
public class GradeController {

    /** What the screen is told about a grade: whether it is retired on the sheet. */
    public record GradeView(String grade, boolean retired) {
    }

    /** A grade to merge into another. */
    public record MergeForm(@NotBlank @Pattern(regexp = "[ABC]") String from,
            @NotBlank @Pattern(regexp = "[ABC]") String into) {
    }

    /** What the screen is told of a merge: the grades and how many people were given the other. */
    public record MergeView(String from, String into, int people) {
    }

    private final GradeService service;
    private final GradeMergeService merges;

    public GradeController(GradeService service, GradeMergeService merges) {
        this.service = service;
        this.merges = merges;
    }

    /** The sheet's grades, in order. */
    @GetMapping
    public List<GradeView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        Set<String> retired = service.retired(sheetId);
        return GradeService.GRADES.stream().map((g) -> new GradeView(g, retired.contains(g))).toList();
    }

    /** Retire a grade on the sheet: the sheet's grades as they are now. */
    @PostMapping("/{grade}/retire")
    public List<GradeView> retire(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        service.retire(sheetId, SignedIn.name(user), grade);
        return list(sheetId);
    }

    /** Merge a grade into another on the sheet; a steward only. */
    @PostMapping("/merge")
    public MergeView merge(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid MergeForm form) {
        int people = merges.merge(sheetId, SignedIn.name(user), form.from(), form.into());
        return new MergeView(form.from(), form.into(), people);
    }
}
package net.officefloor.hq.app.grade;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Merging a grade into another: every person whose grade in force on the sheet's today is the merged
 * grade is given the other from the sheet's today, each edited as the person form would, in list order,
 * then the figures the whole merge moved. A steward only; refused for the same grade twice. Should any edit be refused, nothing is merged.
 */
@Service
public class GradeMergeService {

    private final PersonService service;
    private final PersonRepository people;
    private final RoleService roles;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;

    public GradeMergeService(PersonService service, PersonRepository people, RoleService roles, SheetService sheets,
            Rollups rollups, Audit audit) {
        this.service = service;
        this.people = people;
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** Merge the grade from into the grade into: the number of people given it. */
    @Transactional
    public int merge(String sheetId, String user, String from, String into) {
        if (!GradeService.GRADES.contains(from) || !GradeService.GRADES.contains(into)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "There is no such grade.");
        }
        if (from.equals(into)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A grade cannot be merged into itself.");
        }
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward merges grades.");
        }
        sheets.lock(sheetId);
        Rollups.Rollup before = rollups.take(sheetId);
        audit.recordOnCommit("GRADE_MERGED sheet=" + sheetId + " by=" + user + " from=" + from + " into=" + into);
        LocalDate today = sheets.today(sheetId);
        int merged = 0;
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            if (!from.equals(person.gradeOn(today))) {
                continue;
            }
            service.edit(sheetId, user, person.getId(), person.getVersion(), person.getName(), into, null,
                    person.getTerms(), person.getContact(), false, false);
            merged++;
        }
        rollups.audit(sheetId, user, before);
        return merged;
    }
}
package net.officefloor.hq.app.grade;

import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The grades of a sheet, A, B and C, each of which can be retired: people on a retired grade keep it,
 * but it cannot be given to anyone else.
 */
@Service
public class GradeService {

    public static final List<String> GRADES = List.of("A", "B", "C");

    private final RetiredGradeRepository retired;
    private final SheetService sheets;
    private final Audit audit;

    public GradeService(RetiredGradeRepository retired, SheetService sheets, Audit audit) {
        this.retired = retired;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The grades retired on the sheet. */
    @Transactional(readOnly = true)
    public Set<String> retired(String sheetId) {
        return retired.findBySheetId(sheetId).stream().map(RetiredGrade::getGrade).collect(Collectors.toSet());
    }

    /** Retire a grade on the sheet; refused for a grade that is not one or is already retired. */
    @Transactional
    public void retire(String sheetId, String user, String grade) {
        if (!GRADES.contains(grade)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "There is no such grade.");
        }
        sheets.lock(sheetId);
        if (retired.existsBySheetIdAndGrade(sheetId, grade)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That grade is already retired.");
        }
        retired.saveAndFlush(new RetiredGrade(sheetId, grade, user));
        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + user + " grade=" + grade);
    }
}
package net.officefloor.hq.app.grade;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.util.Objects;

/** A grade retired on a sheet, and who retired it. */
@Entity
@Table(name = "grade_retired")
@IdClass(RetiredGrade.Key.class)
public class RetiredGrade {

    /** A sheet and a grade. */
    public static class Key implements Serializable {

        private String sheetId;
        private String grade;

        protected Key() {
        }

        public Key(String sheetId, String grade) {
            this.sheetId = sheetId;
            this.grade = grade;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Key k && Objects.equals(sheetId, k.sheetId) && Objects.equals(grade, k.grade);
        }

        @Override
        public int hashCode() {
            return Objects.hash(sheetId, grade);
        }
    }

    @Id
    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Id
    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "retired_by", nullable = false)
    private String retiredBy;

    protected RetiredGrade() {
    }

    public RetiredGrade(String sheetId, String grade, String retiredBy) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.retiredBy = retiredBy;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public String getRetiredBy() {
        return retiredBy;
    }
}
package net.officefloor.hq.app.grade;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RetiredGradeRepository extends JpaRepository<RetiredGrade, RetiredGrade.Key> {

    /** The grades retired on the sheet. */
    List<RetiredGrade> findBySheetId(String sheetId);

    /** Whether the grade is retired on the sheet. */
    boolean existsBySheetIdAndGrade(String sheetId, String grade);
}
import { Component, inject, signal } from '@angular/core';
import { GradesStore } from '../../core/grades';
import { GRADES, Grade } from '../../core/people';
import { Session } from '../../core/session';

// The sheet's grades, each shown retired or not, and a form to retire one; a retired grade is refused.
@Component({
  selector: 'app-grades',
  template: `
    <section aria-labelledby="grades-heading">
      <h2 id="grades-heading">Grades</h2>
      <form (submit)="retire($event)" aria-label="Retire a grade">
        <label for="grade-retire-select">Grade to retire</label>
        <select
          id="grade-retire-select"
          data-testid="grade-retire-select"
          [value]="grade()"
          (change)="grade.set(chosen($event)); error.set(null)"
        >
          @for (g of codes; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="grade-retire">Retire grade</button>
        @if (error(); as message) {
          <p role="alert" data-testid="grade-error">{{ message }}</p>
        }
      </form>
      <form (submit)="merge($event)" aria-label="Merge a grade into another">
        <label for="grade-merge-from">Merge grade</label>
        <select
          id="grade-merge-from"
          data-testid="grade-merge-from"
          [value]="mergeFrom()"
          (change)="mergeFrom.set(chosen($event)); error.set(null)"
        >
          @for (g of codes; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="grade-merge-into">into</label>
        <select
          id="grade-merge-into"
          data-testid="grade-merge-into"
          [value]="mergeInto()"
          (change)="mergeInto.set(chosen($event)); error.set(null)"
        >
          @for (g of codes; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="grade-merge">Merge grade</button>
        <span role="status">
          @if (merged(); as m) {
            Merged <strong data-testid="grade-merged">{{ m }}</strong>
          }
        </span>
      </form>
      <table>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">Retired</th>
          </tr>
        </thead>
        <tbody>
          @for (g of store.grades(); track g.grade) {
            <tr [attr.data-testid]="'grade-row-' + g.grade">
              <td data-testid="grade-code">{{ g.grade }}</td>
              <td data-testid="grade-retired">{{ g.retired ? 'yes' : 'no' }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Grades {
  private readonly session = inject(Session);
  protected readonly store = inject(GradesStore);

  protected readonly codes = GRADES;
  protected readonly grade = signal<Grade>('A');
  protected readonly error = signal<string | null>(null);
  protected readonly mergeFrom = signal<Grade>('A');
  protected readonly mergeInto = signal<Grade>('B');
  /** The last merge done from this screen, as "from into into". */
  protected readonly merged = signal('');
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  protected chosen(event: Event): Grade {
    return (event.target as HTMLSelectElement).value as Grade;
  }

  protected async retire(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const grade = this.grade();
    if (this.store.retired(grade)) {
      this.error.set(`The grade ${grade} is already retired.`);
      return;
    }
    this.busy = true;
    try {
      await this.store.retire(sheet, grade);
    } catch {
      this.error.set(`The grade ${grade} could not be retired.`);
    } finally {
      this.busy = false;
    }
  }

  protected async merge(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const from = this.mergeFrom();
    const into = this.mergeInto();
    if (from === into) {
      this.error.set('A grade cannot be merged into itself.');
      return;
    }
    this.busy = true;
    try {
      const done = await this.store.merge(sheet, from, into);
      this.merged.set(`${done.from} into ${done.into}`);
    } catch {
      this.error.set(`The grade ${from} could not be merged into ${into}.`);
    } finally {
      this.busy = false;
    }
  }
}

